def gen(rng):
    def fmt(a, k):
        return f'{len(a)} {k}\n' + ' '.join(map(str, a))
    tests = [fmt([5], 1), fmt([3, 3, 3, 3], 2), fmt([4, 1, 3, 2], 4), fmt([9, 8, 7, 6, 5], 1), fmt([1, 2, 3, 4, 5], 3),
             fmt([2, 1, 2, 1, 2, 1], 3), fmt([-5, 0, -5, 7, -1], 2), fmt([10**9, -10**9, 0], 2)]
    for n in (3, 5, 8, 12, 20, 30):
        for _ in range(2):
            a = [rng.randint(-10, 10) for _ in range(n)]
            tests.append(fmt(a, rng.randint(1, n)))
    n = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)], 50000))
    tests.append(fmt([rng.randint(1, 100) for _ in range(n)], 30000))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)], 100))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)], n))
    return tests
